/* @lc app=leetcode id=2163 lang=kotlin */
class Solution { fun minimumDifference(nums: IntArray): Long = (nums.size / 3).let { n -> LongArray(n + 1).let { l -> LongArray(n + 1).let { r -> java.util.PriorityQueue<Int>(compareByDescending { it }).apply { (0 until n).forEach { add(nums[it]) } }.let { lpq -> (1..n).fold(nums.slice(0 until n).sumOf { it.toLong() }.also { l[0] = it }) { acc, i -> (acc + nums[n + i - 1]).let { ns -> lpq.run { add(nums[n + i - 1]).let { ns - poll().toLong() } }.also { l[i] = it } } } }.let { java.util.PriorityQueue<Int>().apply { (2 * n until 3 * n).forEach { add(nums[it]) } }.let { rpq -> (n - 1 downTo 0).fold(nums.slice(2 * n until 3 * n).sumOf { it.toLong() }.also { r[n] = it }) { acc, i -> (acc + nums[n + i]).let { ns -> rpq.run { add(nums[n + i]).let { ns - poll().toLong() } }.also { r[i] = it } } } } }.let { (0..n).minOf { l[it] - r[it] } } } } } }